def clean(df):
    df = df.copy()
    df = df.drop_duplicates(subset='Order_ID', keep='first')
    df['Category'] = df['Category'].str.strip()
    df['Price'] = df['Price'].str.replace('$', '', regex=False).astype(float)
    df = df[df['Quantity'] >= 1]
    return df

def answer(df):
    return df.groupby('Region')['Quantity'].sum().astype(int).to_dict()
